import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

export type Insight = {
  /**
   * The anticipated number of days your current available and inbound inventory will last, based on
   * your daily forecasted sales demand.
   */
  daysOfSupply?: number;
  /**
   * The number of units Walmart suggests you send to WFS based on the item's forecasted sales
   * demand. These suggestions are generated by algorithms considering several factors including
   * past sales, seasonality, listing, quality, pricing, and more.
   */
  suggestedUnits?: number;
  /**
   * Estimated dollar amount in sales if the suggested number of units are sent to WFS and sold
   * within 8 weeks.
   */
  forecastedSalesLift?: number;
  /** Indicates whether the item is identified as a customer favorite based on customer demand. */
  customerFavorite?: boolean;
};

export const insightSchema: Schema<Insight> = s.object<Insight>({
  daysOfSupply: s.optional(s.int()),
  suggestedUnits: s.optional(s.int()),
  forecastedSalesLift: s.optional(s.float64()),
  customerFavorite: s.optional(s.boolean()),
});
